CREATE     VIEW [FO].[vwVendTable]
AS 
SELECT 
	T1.[DATAAREAID],
	T1.[ACCOUNTNUM] AS [ACCOUNTNUM],
	T10.[NAME] AS [NAME],
	T18.[ADDRESS],
	T10.[PRIMARYCONTACTPHONE] AS [PHONE],
	T10.[PRIMARYCONTACTFAX] AS [TELEFAX],
	T1.[INVOICEACCOUNT],
	T1.[VENDGROUP],
	T1.[PAYMTERMID],
	T1.[CASHDISC],
	T1.[CURRENCY],
	T1.[CURRENCY] AS [CURRENCYCODE],
	T1.[BLOCKED],
	T1.[ONETIMEVENDOR],
	T10.[PRIMARYCONTACTTELEX] AS [TELEX],
	T1.[PAYMID],
	T18.COUNTRYREGIONID AS [COUNTRYREGIONID],
	T1.[INVENTLOCATION],
	T1.[YOURACCOUNTNUM],
	T1.[DLVTERM],
	T1.[DLVMODE],
	T1.[BANKACCOUNT],
	T1.[PAYMMODE],
	T1.[PAYMSPEC],
	T18.[ZIPCODE],
	T18.[STATE],
	--T1.[country],
	T10.[PRIMARYCONTACTURL] AS [URL],
	T10.[PRIMARYCONTACTEMAIL] AS [EMAIL],
	--T1.[cellularphone],
	--T1.[phonelocal],
	T1.[FREIGHTZONE],
	T1.[CREDITRATING],
	T1.[CREDITMAX],
	T10.[NAMEALIAS],
	T1.[ITEMBUYERGROUPID],
	T1.[CONTACTPERSONID],
	T1.[PURCHPOOLID],
	T1.[PURCHAMOUNTPURCHASEORDER],
	T1.[INCLTAX],
	T1.[VENDITEMGROUPID],
	T1.[NUMBERSEQUENCEGROUP],
	T10.[LANGUAGEID],
	T1.[PAYMDAYID],
	T1.[DESTINATIONCODEID],
	T1.[LINEOFBUSINESSID],
	T1.[BANKCENTRALBANKPURPOSETEXT],
	T18.[CITY],
	T18.[STREET],
	--T1.[offsetaccount],
	T1.[OFFSETACCOUNTTYPE],
	T1.[PURCHCALENDARID],
	--T1.[pager],
	--T1.[sms],
	T10.[PARTYNUMBER] AS [PARTYID],
	T1.[TAXWITHHOLDCALCULATE],
	T1.[NAMECONTROL],
	T1.[INVENTSITEID],
	T1.[SEGMENTID],
	T1.[SUBSEGMENTID],
	T1.[COMPANYCHAINID],
	--T1.[maincontactid],
	T1.[SMALLBUSINESS],
	T10.[PARTYTYPE],
	T1.[LOCALLYOWNED],
	T1.[BIDONLY],
	T1.[USECASHDISC],
	T1.[VATNUM],
	T1.[TAXGROUP],
	T1.[PAYMSCHED],
	T1.[PAYMTERMID] + '_' + T1.[DATAAREAID] AS Paymterm_Key,
	T1.[VENDGROUP] + '_' + T1.[DATAAREAID] AS VendGroup_Key,
	T1.BLOCKEDRELEASEDATE
FROM [synapse_fo].[VENDTABLE] T1
LEFT OUTER JOIN [synapse_fo].[COMPANYNAFCODE] T2 ON (
		(
			(T1.COMPANYNAFCODE = T2.RECID)
			AND (T1.DATAAREAID = T2.DATAAREAID)
			)
		AND (T1.PARTITION = T2.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[VENDINVOICEDECLARATION_IS] T3 ON (
		(
			(T1.VENDINVOICEDECLARATION_IS = T3.RECID)
			AND (T1.DATAAREAID = T3.DATAAREAID)
			)
		AND (T1.PARTITION = T3.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[LVPAYMTRANSCODES] T4 ON (
		(
			(T1.LVPAYMTRANSCODES = T4.RECID)
			AND (T1.DATAAREAID = T4.DATAAREAID)
			)
		AND (T1.PARTITION = T4.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[HCMWORKER] T5 ON (
		(T1.MAINCONTACTWORKER = T5.RECID)
		AND (T1.PARTITION = T5.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[TAX1099FIELDS] T6 ON (
		(
			(T1.TAX1099FIELDS = T6.RECID)
			AND (T1.DATAAREAID = T6.DATAAREAID)
			)
		AND (T1.PARTITION = T6.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[VENDEXCEPTIONGROUP] T7 ON (
		(
			(T1.VENDEXCEPTIONGROUP = T7.RECID)
			AND (T1.DATAAREAID = T7.DATAAREAID)
			)
		AND (T1.PARTITION = T7.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[DIMENSIONSETENTITY_RICS] T8 ON (
		(T1.DEFAULTDIMENSION = T8.RECID)
		AND (T1.PARTITION = T8.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[DIMENSIONCOMBINATIONENTITY_RICS] T9 ON (
		(T1.OFFSETLEDGERDIMENSION = T9.RECID)
		AND (T1.PARTITION = T9.PARTITION)
		)
CROSS JOIN [synapse_fo].[DIRPARTYBASEENTITY_RICS] T10
LEFT OUTER JOIN [synapse_fo].[PURCHJOURNALAUTOSUMMARY] T11 ON (
		(
			(
				(
					(T11.MODULETYPE = 0)
					AND (T1.DATAAREAID = T11.DATAAREAID)
					)
				AND (T1.PARTITION = T11.PARTITION)
				)
			AND (
				(
					(T1.ACCOUNTNUM = T11.VENDACCOUNT)
					AND (T1.DATAAREAID = T11.DATAAREAID)
					)
				AND (T1.PARTITION = T11.PARTITION)
				)
			)
		AND (T11.DOCUMENTSTATUS = 2)
		)
LEFT OUTER JOIN [synapse_fo].[PURCHJOURNALAUTOSUMMARY] T12 ON (
		(
			(
				(
					(T12.MODULETYPE = 0)
					AND (T1.DATAAREAID = T12.DATAAREAID)
					)
				AND (T1.PARTITION = T12.PARTITION)
				)
			AND (
				(
					(T1.ACCOUNTNUM = T12.VENDACCOUNT)
					AND (T1.DATAAREAID = T12.DATAAREAID)
					)
				AND (T1.PARTITION = T12.PARTITION)
				)
			)
		AND (T12.DOCUMENTSTATUS = 5)
		)
LEFT OUTER JOIN [synapse_fo].[PURCHJOURNALAUTOSUMMARY] T13 ON (
		(
			(
				(
					(T13.MODULETYPE = 0)
					AND (T1.DATAAREAID = T13.DATAAREAID)
					)
				AND (T1.PARTITION = T13.PARTITION)
				)
			AND (
				(
					(T1.ACCOUNTNUM = T13.VENDACCOUNT)
					AND (T1.DATAAREAID = T13.DATAAREAID)
					)
				AND (T1.PARTITION = T13.PARTITION)
				)
			)
		AND (T13.DOCUMENTSTATUS = 6)
		)
LEFT OUTER JOIN [synapse_fo].[PURCHJOURNALAUTOSUMMARY] T14 ON (
		(
			(
				(
					(T14.MODULETYPE = 0)
					AND (T1.DATAAREAID = T14.DATAAREAID)
					)
				AND (T1.PARTITION = T14.PARTITION)
				)
			AND (
				(
					(T1.ACCOUNTNUM = T14.VENDACCOUNT)
					AND (T1.DATAAREAID = T14.DATAAREAID)
					)
				AND (T1.PARTITION = T14.PARTITION)
				)
			)
		AND (T14.DOCUMENTSTATUS = 7)
		)
LEFT OUTER JOIN [synapse_fo].[VEND1099OIDDETAIL] T15 ON (
		(
			(T1.ACCOUNTNUM = T15.VENDTABLE)
			AND (T1.DATAAREAID = T15.DATAAREAID)
			)
		AND (T1.PARTITION = T15.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[TAXINFORMATIONVENDTABLE_IN] T16 ON (
		(
			(T1.ACCOUNTNUM = T16.VENDTABLE)
			AND (T1.DATAAREAID = T16.DATAAREAID)
			)
		AND (T1.PARTITION = T16.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[VENDINFOZAKAT_SA] T17 ON (
		(
			(T1.ACCOUNTNUM = T17.VENDACCOUNT)
			AND (T1.DATAAREAID = T17.DATAAREAID)
			)
		AND (T1.PARTITION = T17.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[LOGISTICSPOSTALADDRESSBASEENTITY_RICS] T18 ON (
		(
			(T10.PRIMARYADDRESSLOCATION = T18.LOCATIONRECID)
			AND (T10.PARTITION = T18.PARTITION)
			)
		AND (
			(
				T18.VALIDFROM <= GETUTCDATE()
				)
			AND (
				T18.VALIDTO >= GETUTCDATE()
				)
			)
		)
LEFT OUTER JOIN [synapse_fo].[LOGISTICSLOCATIONEXT] T19 ON (
		(
			(T18.RECID = T19.LOCATION)
			AND (T18.PARTITION = T19.PARTITION)
			)
		AND (T19.DATAAREAID = T1.DATAAREAID)
		)
WHERE (
		(T1.PARTY = T10.RECID)
		AND (T1.PARTITION = T10.PARTITION)
		)
